connection.console:
SELECT table_name, column_name, data_type, character_maximum_length AS length FROM information_schema.columns WHERE table_schema = 'public' ORDER BY table_name, ordinal_position; SELECT conname AS constraint_name, contype AS type, enr.relname AS table_name FROM pg_constraint c JOIN pg_class enr ON c.conrelid = enr.oid WHERE c.connamespace = 'public'::regnamespace AND enr.relname IN ('movies', 'showtimes', 'rooms', 'seats', 'tickets', 'reports', 'users');
-- ========================================================================= -- KHỞI TẠO CẤU TRÚC BẢNG (Chạy toàn bộ khối này trước) -- =========================================================================
CREATE TABLE users ( user_id BIGSERIAL PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, email VARCHAR(100) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, phone VARCHAR(20) UNIQUE NOT NULL, gender VARCHAR(10), role VARCHAR(20) NOT NULL );
CREATE TABLE movies ( movie_id BIGSERIAL PRIMARY KEY, title VARCHAR(200) NOT NULL, description TEXT, trailer_url VARCHAR(500), movie_format VARCHAR(50), status INT, duration INT, genre VARCHAR(100), age_rating VARCHAR(10), release_date DATE, image VARCHAR(500), author VARCHAR(100) );
CREATE TABLE theaters ( theater_id VARCHAR(20) PRIMARY KEY, name VARCHAR(100), city VARCHAR(50), location VARCHAR(255), address VARCHAR(500), phone VARCHAR(20), operating_hours VARCHAR(100) );
CREATE TABLE rooms ( room_id VARCHAR(10) PRIMARY KEY, theater_id VARCHAR(20) REFERENCES theaters(theater_id), room_number INT, total_seats INT );
CREATE TABLE seats ( seat_id VARCHAR(10) PRIMARY KEY, room_id VARCHAR(10) REFERENCES rooms(room_id), seat_number VARCHAR(10), seat_type VARCHAR(20) );
CREATE TABLE showtimes ( showtime_id VARCHAR(50) PRIMARY KEY, -- Đã tăng kích thước movie_id BIGINT REFERENCES movies(movie_id), room_id VARCHAR(10) REFERENCES rooms(room_id), show_date DATE, start_time TIME, ticket_price NUMERIC );
CREATE TABLE tickets ( ticket_id VARCHAR(50) PRIMARY KEY, -- Đã tăng kích thước showtime_id VARCHAR(50) REFERENCES showtimes(showtime_id), user_id BIGINT REFERENCES users(user_id), total_price NUMERIC, status VARCHAR(20), booking_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE booking_seats ( id BIGSERIAL PRIMARY KEY, booking_id VARCHAR(50) REFERENCES tickets(ticket_id), seat_id VARCHAR(10) REFERENCES seats(seat_id) );
CREATE TABLE payments ( payment_id BIGSERIAL PRIMARY KEY, booking_id VARCHAR(50) REFERENCES tickets(ticket_id), amount NUMERIC, payment_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP, payment_method VARCHAR(50), transaction_id VARCHAR(100) );
CREATE TABLE vouchers ( voucher_code VARCHAR(50) PRIMARY KEY, discount_percent NUMERIC, expiry_date DATE, is_active BOOLEAN DEFAULT TRUE );
CREATE TABLE reports ( report_id VARCHAR(50) PRIMARY KEY, theater_id VARCHAR(20) REFERENCES theaters(theater_id), movie_id BIGINT REFERENCES movies(movie_id), report_date DATE, total_revenue NUMERIC );
-- ========================================================================= -- BƠM DỮ LIỆU CƠ BẢN (Users, Theaters, Movies) -- =========================================================================
